create or replace function private.command_post_order_payment_attributed(p_organization_id uuid,p_order_id uuid,p_amount numeric,p_payment_date date,p_method text,p_reference text,p_payer_type text,p_payer_name text,p_idempotency_key text) returns uuid language plpgsql security definer set search_path='pg_catalog','public','app','private' as $$ declare v_order app.orders%rowtype; v_payment uuid; v_paid numeric; v_actor uuid:=(select auth.uid()); v_type text:=coalesce(nullif(trim(p_payer_type),''),'guardian'); begin if not private.has_module_access(p_organization_id,'commerce',true) then raise exception 'Not authorized'; end if; if p_amount is null or p_amount<=0 then raise exception 'Amount must be greater than zero'; end if; if p_idempotency_key is null or length(trim(p_idempotency_key))<8 then raise exception 'Idempotency key required'; end if; if v_type not in ('guardian','sponsor','player','organization','other') then raise exception 'Invalid payer type'; end if; if v_type='sponsor' and nullif(trim(coalesce(p_payer_name,'')),'') is null then raise exception 'Sponsor name required'; end if; select * into v_order from app.orders where organization_id=p_organization_id and id=p_order_id for update; if not found then raise exception 'Order not found'; end if; if v_order.status not in ('pending_payment','partial_payment') then raise exception 'Order is not open for payment'; end if; select p.id into v_payment from app.payments p where p.organization_id=p_organization_id and p.idempotency_key=trim(p_idempotency_key); if v_payment is not null then if not exists(select 1 from app.order_payments where organization_id=p_organization_id and order_id=p_order_id and payment_id=v_payment) then raise exception 'Idempotency key already belongs to another payment context'; end if; return v_payment; end if; v_paid:=private.order_paid_amount(p_organization_id,p_order_id); if v_paid+p_amount>coalesce(v_order.total,0)+0.005 then raise exception 'Payment exceeds order balance'; end if; insert into app.payments(organization_id,player_id,amount,payment_date,method,reference,concept,status,source,category,idempotency_key,payer_type,payer_name,payment_purpose,credit_status,created_at,updated_at) values(p_organization_id,v_order.player_id,p_amount,coalesce(p_payment_date,current_date),coalesce(nullif(trim(p_method),''),'other'),nullif(trim(p_reference),''),'Abono pedido '||v_order.folio,'posted','tanneros_v2','Pedido Tienda',trim(p_idempotency_key),v_type,nullif(trim(p_payer_name),''),'commerce','not_applicable',now(),now()) returning id into v_payment; insert into app.order_payments(organization_id,order_id,payment_id,amount) values(p_organization_id,p_order_id,v_payment,p_amount); v_paid:=v_paid+p_amount; update app.orders set status=case when v_paid+0.005>=total then 'paid' else 'partial_payment' end,updated_at=now() where id=p_order_id and organization_id=p_organization_id; insert into app.domain_events(organization_id,event_type,aggregate_type,aggregate_id,payload,actor_user_id,request_id) values(p_organization_id,'OrderPaymentPosted','order',p_order_id,jsonb_build_object('paymentId',v_payment,'amount',p_amount,'paidTotal',v_paid,'payerType',v_type,'payerName',nullif(trim(p_payer_name),'')),v_actor,trim(p_idempotency_key)); return v_payment; end $$;
create or replace function private.query_order_detail(p_organization_id uuid,p_order_id uuid) returns jsonb language plpgsql stable security definer set search_path='pg_catalog','app','private' as $$ declare v_order jsonb; v_items jsonb; v_payments jsonb; v_paid numeric; v_readiness jsonb; v_cost numeric; v_missing_cost bigint; begin if not private.has_module_access(p_organization_id,'commerce',false) then raise exception 'Not authorized'; end if; select to_jsonb(o) into v_order from app.orders o where o.id=p_order_id and o.organization_id=p_organization_id; if v_order is null then raise exception 'Order not found'; end if; select coalesce(jsonb_agg(jsonb_build_object('id',i.id,'productId',i.product_id,'description',i.description,'quantity',i.quantity,'unitPrice',i.unit_price,'unitCost',i.unit_cost,'attributes',i.attributes) order by i.id),'[]'::jsonb),coalesce(sum(coalesce(i.unit_cost,0)*i.quantity),0),count(*) filter(where i.unit_cost is null) into v_items,v_cost,v_missing_cost from app.order_items i where i.order_id=p_order_id and i.organization_id=p_organization_id; select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'amount',op.amount,'paymentDate',p.payment_date,'method',p.method,'reference',p.reference,'status',p.status,'payerType',p.payer_type,'payerName',p.payer_name,'createdAt',op.created_at) order by op.created_at,p.id),'[]'::jsonb) into v_payments from app.order_payments op join app.payments p on p.id=op.payment_id and p.organization_id=op.organization_id where op.organization_id=p_organization_id and op.order_id=p_order_id; v_paid:=private.order_paid_amount(p_organization_id,p_order_id); v_readiness:=private.order_readiness(p_organization_id,p_order_id); return jsonb_build_object('order',v_order,'items',v_items,'payments',v_payments,'paidAmount',v_paid,'balance',greatest(0,coalesce((v_order->>'total')::numeric,0)-v_paid),'costTotal',case when v_missing_cost=0 then v_cost else null end,'costComplete',v_missing_cost=0,'grossProfitExpected',case when v_missing_cost=0 then coalesce((v_order->>'total')::numeric,0)-v_cost else null end,'readiness',v_readiness); end $$;
create or replace function private.command_post_batch_supplier_payment(p_organization_id uuid,p_batch_id uuid,p_amount numeric,p_expense_date date,p_method text,p_reference text,p_notes text,p_idempotency_key text) returns uuid language plpgsql security definer set search_path='pg_catalog','app','private' as $$ declare v_batch app.production_batches%rowtype; v_id uuid; v_paid numeric; v_actor uuid:=(select auth.uid()); begin if not private.has_module_access(p_organization_id,'accounting',true) then raise exception 'Not authorized'; end if; if p_amount is null or p_amount<=0 then raise exception 'Amount must be greater than zero'; end if; if p_idempotency_key is null or length(trim(p_idempotency_key))<8 then raise exception 'Idempotency key required'; end if; select * into v_batch from app.production_batches where id=p_batch_id and organization_id=p_organization_id for update; if not found then raise exception 'Production batch not found'; end if; if v_batch.status='cancelled' then raise exception 'Cancelled batch cannot receive supplier payments'; end if; select id into v_id from app.expenses where organization_id=p_organization_id and idempotency_key=trim(p_idempotency_key); if v_id is not null then return v_id; end if; select coalesce(sum(amount),0) into v_paid from app.expenses where organization_id=p_organization_id and production_batch_id=p_batch_id and status='posted'; if v_paid+p_amount>coalesce(v_batch.cost_total,0)+0.005 then raise exception 'Supplier payment exceeds batch payable'; end if; insert into app.expenses(organization_id,amount,expense_date,category,concept,method,reference,supplier_name,status,source,notes,idempotency_key,metadata,production_batch_id,created_by_user_id,created_at,updated_at) values(p_organization_id,p_amount,coalesce(p_expense_date,current_date),'Proveedor producción','Pago proveedor '||v_batch.folio,coalesce(nullif(trim(p_method),''),'other'),nullif(trim(p_reference),''),v_batch.supplier_name,'posted','tanneros_v2',nullif(trim(coalesce(p_notes,'')),''),trim(p_idempotency_key),jsonb_build_object('productionBatchId',p_batch_id,'batchFolio',v_batch.folio,'batchType',v_batch.batch_type),p_batch_id,v_actor,now(),now()) returning id into v_id; insert into app.domain_events(organization_id,event_type,aggregate_type,aggregate_id,payload,actor_user_id,request_id) values(p_organization_id,'ProductionBatchSupplierPaymentPosted','production_batch',p_batch_id,jsonb_build_object('expenseId',v_id,'amount',p_amount,'supplierPaidTotal',v_paid+p_amount,'supplierPayable',greatest(0,v_batch.cost_total-v_paid-p_amount)),v_actor,trim(p_idempotency_key)); return v_id; end $$;
create or replace function private.query_production_batch_finance(p_organization_id uuid,p_batch_id uuid) returns jsonb language plpgsql stable security definer set search_path='pg_catalog','app','private' as $$ declare v_batch app.production_batches%rowtype; v_supplier_paid numeric; v_collected numeric; v_orders jsonb; v_expenses jsonb; begin if not (private.has_module_access(p_organization_id,'commerce',false) or private.has_module_access(p_organization_id,'accounting',false)) then raise exception 'Not authorized'; end if; select * into v_batch from app.production_batches where id=p_batch_id and organization_id=p_organization_id; if not found then raise exception 'Production batch not found'; end if; select coalesce(sum(e.amount),0),coalesce(jsonb_agg(jsonb_build_object('id',e.id,'amount',e.amount,'date',e.expense_date,'method',e.method,'reference',e.reference,'supplier',e.supplier_name,'status',e.status,'createdBy',e.created_by_user_id) order by e.expense_date,e.created_at) filter(where e.id is not null),'[]'::jsonb) into v_supplier_paid,v_expenses from app.expenses e where e.organization_id=p_organization_id and e.production_batch_id=p_batch_id and e.status='posted'; select coalesce(sum(private.order_paid_amount(p_organization_id,bo.order_id)),0),coalesce(jsonb_agg(jsonb_build_object('orderId',o.id,'folio',o.folio,'customer',o.customer_name,'sale',bo.sale_snapshot,'cost',bo.cost_snapshot,'collected',private.order_paid_amount(p_organization_id,o.id),'customerBalance',greatest(0,bo.sale_snapshot-private.order_paid_amount(p_organization_id,o.id)),'grossProfitExpected',bo.sale_snapshot-bo.cost_snapshot,'payments',(select coalesce(jsonb_agg(jsonb_build_object('amount',op.amount,'date',p.payment_date,'method',p.method,'reference',p.reference,'payerType',p.payer_type,'payerName',p.payer_name) order by p.payment_date,op.created_at),'[]'::jsonb) from app.order_payments op join app.payments p on p.id=op.payment_id and p.organization_id=op.organization_id where op.organization_id=p_organization_id and op.order_id=o.id)) order by o.folio) filter(where o.id is not null),'[]'::jsonb) into v_collected,v_orders from app.production_batch_orders bo join app.orders o on o.id=bo.order_id and o.organization_id=bo.organization_id where bo.organization_id=p_organization_id and bo.batch_id=p_batch_id; return jsonb_build_object('batch',to_jsonb(v_batch),'customerCollected',v_collected,'supplierPaid',v_supplier_paid,'supplierPayable',greatest(0,coalesce(v_batch.cost_total,0)-v_supplier_paid),'grossProfitExpected',coalesce(v_batch.sales_total,0)-coalesce(v_batch.cost_total,0),'cashNetCurrent',v_collected-v_supplier_paid,'orders',v_orders,'supplierPayments',v_expenses); end $$;
create or replace function private.command_post_expense(p_organization_id uuid,p_amount numeric,p_expense_date date,p_category text,p_method text,p_reference text,p_concept text,p_metadata jsonb,p_idempotency_key text) returns uuid language plpgsql security definer set search_path='pg_catalog','app','private' as $$ declare v_id uuid; v_actor uuid:=(select auth.uid()); begin if not private.has_module_access(p_organization_id,'accounting',true) then raise exception 'Not authorized'; end if; if p_amount is null or p_amount<=0 then raise exception 'Expense amount must be greater than zero'; end if; if nullif(trim(coalesce(p_category,'')),'') is null then raise exception 'Expense category required'; end if; if nullif(trim(coalesce(p_concept,'')),'') is null then raise exception 'Expense concept required'; end if; if p_idempotency_key is null or length(trim(p_idempotency_key))<8 then raise exception 'Idempotency key required'; end if; select id into v_id from app.expenses where organization_id=p_organization_id and idempotency_key=trim(p_idempotency_key); if v_id is not null then return v_id; end if; insert into app.expenses(organization_id,amount,expense_date,category,method,reference,concept,status,source,metadata,idempotency_key,created_by_user_id,created_at,updated_at) values(p_organization_id,p_amount,coalesce(p_expense_date,current_date),trim(p_category),coalesce(nullif(trim(p_method),''),'other'),nullif(trim(p_reference),''),trim(p_concept),'posted','tanneros_v2',coalesce(p_metadata,'{}'::jsonb),trim(p_idempotency_key),v_actor,now(),now()) returning id into v_id; insert into app.domain_events(organization_id,event_type,aggregate_type,aggregate_id,payload,actor_user_id,request_id) values(p_organization_id,'ExpensePosted','expense',v_id,jsonb_build_object('amount',p_amount,'category',trim(p_category),'expenseDate',coalesce(p_expense_date,current_date)),v_actor,trim(p_idempotency_key)); return v_id; exception when unique_violation then select id into v_id from app.expenses where organization_id=p_organization_id and idempotency_key=trim(p_idempotency_key); if v_id is null then raise; end if; return v_id; end $$;
create or replace function private.command_void_expense(p_organization_id uuid,p_expense_id uuid,p_reason text) returns void language plpgsql security definer set search_path='pg_catalog','app','private' as $$ declare v app.expenses%rowtype; v_actor uuid:=(select auth.uid()); begin if not private.has_module_access(p_organization_id,'accounting',true) then raise exception 'Not authorized'; end if; if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'Void reason required'; end if; select * into v from app.expenses where id=p_expense_id and organization_id=p_organization_id for update; if not found then raise exception 'Expense not found'; end if; if v.status<>'posted' then raise exception 'Only posted expenses can be voided'; end if; update app.expenses set status='void',voided_at=now(),void_reason=trim(p_reason),voided_by_user_id=v_actor,updated_at=now() where id=v.id; insert into app.domain_events(organization_id,event_type,aggregate_type,aggregate_id,payload,actor_user_id) values(p_organization_id,'ExpenseVoided','expense',v.id,jsonb_build_object('reason',trim(p_reason),'amount',v.amount,'productionBatchId',v.production_batch_id),v_actor); end $$;
create or replace function public.v2_post_order_payment_attributed(organization_id uuid,order_id uuid,amount numeric,payment_date date,method text,reference text,payer_type text,payer_name text,idempotency_key text) returns uuid language sql security definer set search_path='pg_catalog','private' as $$ select private.command_post_order_payment_attributed(organization_id,order_id,amount,payment_date,method,reference,payer_type,payer_name,idempotency_key) $$;
create or replace function public.v2_post_batch_supplier_payment(organization_id uuid,batch_id uuid,amount numeric,expense_date date,method text,reference text,notes text,idempotency_key text) returns uuid language sql security definer set search_path='pg_catalog','private' as $$ select private.command_post_batch_supplier_payment(organization_id,batch_id,amount,expense_date,method,reference,notes,idempotency_key) $$;
create or replace function public.v2_production_batch_finance(organization_id uuid,batch_id uuid) returns jsonb language sql stable security definer set search_path='pg_catalog','private' as $$ select private.query_production_batch_finance(organization_id,batch_id) $$;
revoke execute on function public.v2_post_order_payment_attributed(uuid,uuid,numeric,date,text,text,text,text,text),public.v2_post_batch_supplier_payment(uuid,uuid,numeric,date,text,text,text,text),public.v2_production_batch_finance(uuid,uuid) from public,anon; grant execute on function public.v2_post_order_payment_attributed(uuid,uuid,numeric,date,text,text,text,text,text),public.v2_post_batch_supplier_payment(uuid,uuid,numeric,date,text,text,text,text),public.v2_production_batch_finance(uuid,uuid) to authenticated;;
